<?php declare(strict_types=1);require_once __DIR__.'/auth.php';$u=portal_require();$q=$db->prepare('SELECT client_id FROM client_portal_users WHERE id=?');$q->execute([$u['id']]);$client=(int)$q->fetchColumn();$q=$db->prepare('SELECT name,category,file_path,created_at FROM client_portal_documents WHERE client_id=? AND is_visible=1 ORDER BY created_at DESC');$q->execute([$client]);$rows=$q->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Documents</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><main class="container py-4"><a href="index.php">← Dashboard</a><h1 class="h3 mt-3">Documents</h1><table class="table"><thead><tr><th>Document</th><th>Category</th><th>Date</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['name'])?></td><td><?=htmlspecialchars($r['category']??'')?></td><td><?=htmlspecialchars($r['created_at'])?></td><td><a href="download.php?file=<?=urlencode($r['file_path'])?>">View</a></td></tr><?php endforeach;?></tbody></table></main></body></html>